-- L19-l1-kpopdle-data-fixes.sql (lane kpopdle, run O1, owner 2026-11-09; audit 05 section 5, Part A items 0 to 8 and Part B as commented blocks; generated by apps/quiz/scripts/gen-kpopdle-launch.mjs, do not edit by hand)
--
-- What:   the data corrections of the audit of Kpopdle Idol, each keyed by id and name (K1) or Wikidata QID and name (K2) AND by the exact wrong value
--         the audit read in production on 2026-11-08, so a row that holds anything else is left alone and named in a notice:
--         1. status: dle_curation excluded for Taeil (74) and Mark (80), who left NCT (they stay in idols, active, for the public pages: Part B1 decides that);
--            they leave the answers NOW (owner decision B1, 2026-11-09): the file redraws the coming days that held them, see WHEN;
--         2. agency (groups.record_label, the Korean company that formed and manages the group, never a US distribution label): BTS and TXT to BigHit Music,
--            IVE to Starship Entertainment, ATEEZ to KQ Entertainment, RIIZE and aespa to SM Entertainment, NewJeans to ADOR; the names go into public.agencies
--            (022) with the same strings so the slug matches (only the missing ones, stamped created_at 2026-11-09 00:00 UTC so the rollback deletes exactly those).
--            TWICE, Stray Kids, ITZY, (G)I-DLE, SEVENTEEN, KATSEYE and CORTIS were read in production on 2026-11-08 and are right: not in this file;
--         3. positions: Maknae added to 10 idols, Leader added to Taeyeon and Junkyu, Leader taken off Minji (NewJeans has no leader on Wikipedia). Hoshi and Woozi
--            are fixed by the view of L20, not here;
--         4. group cell: Go Won (Q58825794) gets Loossemble in idol_other_groups, like Hyunjin, Yeojin and Hyeju (Part B4 is the alternative);
--         5. debut year (the 021c rule: first official release as a member of a debuted group): Jay B and Jinyoung 2014 to 2012 (JJ Project), JiU, SuA, Siyeon,
--            Yoohyeon and Dami 2017 to 2014 (MINX);
--         6. nationality spelling: "People's Republic of China" to "China" on Ningning (33), Jun (42), Yuqi (58), Lay (170) and Qian Kun (89), the label the K2 rows
--            and the French words already use. Same fact, other spelling: their wikidata source rows stay valid and no row is added;
--         7. ASTRO groups.inception_date 2016-01-01 to 2016-02-23 (not shown by the game);
--         8. dle_refresh_entities('kpopdle-idol') when the game has a snapshot (never dle_build_bank), then dle_reschedule('L19', 'kpopdle-idol').
--         One entity_sources row (source wikipedia, source_ref "rev <id>", source_url, fetched_at 2026-11-09 00:00 UTC) per corrected value: the revision of the
--         English Wikipedia page read on 2026-11-09. The debut-year rows of wikidata and musicbrainz that named the old year are replaced (one source per stored
--         year, as 021c does; the rollback puts them back). The old wikidata "record_label" rows of the seven groups stay.
--         Not touched: any other column, any other idol, idols.active, needs_review, dle_daily_stats.
--         Sources read on 2026-11-09 (revision ids in the rows below): https://en.wikipedia.org/wiki/ pages BTS, Ive_(group), Ateez, Riize, Tomorrow_X_Together,
--         NewJeans, Aespa, NCT_(group), Hybe, Loossemble, JJ_Project, Dreamcatcher_(group), Astro_(South_Korean_band), Girls'_Generation, Treasure_(band),
--         Zerobaseone, P1Harmony, Jung_Kook, Lisa_(rapper), Tzuyu, Ningning, Sehun, Taemin.
-- Needs:  019, 020, 021a, 021c, 021d (the K2 rows), 022 (public.agencies), 011 (entity_sources.source_url and source wikipedia).
-- WHEN:   apply by the owner after a backup, never during a build, never between 23:50 and 00:30 UTC, one launch file at a time, the Verify lines run after it. Nothing waits for a date: the file
--         redraws itself the coming days (tomorrow to today + 364; never today, never a served date) whose answer it removes (Taeil and Mark), after saving the whole bank of the game in
--         dle_schedule_backup; the rollback puts that bank and the pool_hash back. Every guess is stored as an entity id and its colours are computed on read: a corrected value re-colours
--         the past days (R12 of the audit), which is wanted because the old value was wrong. The snapshot dle_entities is refreshed in the same transaction.
-- Effect: kpopquiz.org (data only, no template change): the Label line of the Verse fact rail, the about page, the group hub and the answer-first text of BTS, TXT,
--         IVE, ATEEZ, RIIZE, NewJeans and aespa; the position tags of the idols in item 3 and the nationality of the five in item 6 on their member pages; the debut
--         year of the seven in item 5 where it is read; the ASTRO debut date. Taeil and Mark stay on the member counts until Part B1.
-- Verify: select count(*) from public.groups where site_id = 'kpop' and (name, record_label) in (('BTS', 'BigHit Music'), ('TXT', 'BigHit Music'), ('IVE', 'Starship Entertainment'), ('ATEEZ', 'KQ Entertainment'), ('RIIZE', 'SM Entertainment'), ('NewJeans', 'ADOR'), ('aespa', 'SM Entertainment'));   expect 7
-- Verify: select record_label from public.groups where site_id = 'kpop' and name = 'aespa';   expect SM Entertainment
-- Verify: select count(*) from public.idols where id in (33, 42, 58, 89, 170) and nationality = 'China';   expect 5
-- Verify: select count(*) from public.idols where id in (7, 11, 29, 33, 151, 176, 196) and 'Maknae' = any(positions);   expect 7
-- Verify: select array_to_string(positions, ',') from public.idols where id = 34;   expect Vocalist
-- Verify: select string_agg(debut_year::text, ',' order by wikidata_qid) from public.idols where wikidata_qid in ('Q491048', 'Q492313', 'Q59313184', 'Q59313270', 'Q59313326', 'Q59313479', 'Q59313527');   expect 2012,2012,2014,2014,2014,2014,2014
-- Verify: select count(*) from public.dle_entities where game_id = 'kpopdle-idol' and can_be_target;   expect 210
-- Verify: select count(*) from public.dle_entities where game_id = 'kpopdle-idol' and entity_id in ('74', '80') and can_be_target;   expect 0
-- Verify: select count(*) from public.dle_schedule where game_id = 'kpopdle-idol' and entity_id in ('74', '80');   expect 0
-- Verify: select count(*) from public.dle_schedule s join public.dle_games g on g.id = s.game_id join public.dle_entities e on e.game_id = s.game_id and e.entity_id = s.entity_id where s.game_id = 'kpopdle-idol' and not (e.can_be_target and e.in_pool) and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(1, 364) as k);   expect 0
-- Verify: select count(*) from public.dle_schedule_backup where file = 'L19' and game_id = 'kpopdle-idol';   expect 365
-- Undo:   L19-l1-kpopdle-data-fixes.rollback.sql (puts back the exact previous values, only where a row still holds the value this file wrote, and the saved calendar).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing.

do $o1l19$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

-- Redraw of the scheduled answers a file removes (owner rule 2026-11-09: no waiting for a date). dle_reschedule saves the whole bank of the game and its pool_hash
-- (dle_schedule_backup, first snapshot kept), then gives every coming day (tomorrow to today + 364; never today, never a date already served) whose entity is no longer a
-- valid target (can_be_target, in_pool, not excluded) another valid target: the first by md5(game:bank_day:entity) that is scheduled neither in the 30 days after today nor
-- within 30 days of that date (state as it stands, picks already made included); else the first not scheduled in the 30 days after today; else any valid target.
-- dle_reschedule_undo puts the saved bank and pool_hash back (except today and the served dates) and deletes the saved rows. Both are locked away from the browser roles.
create table if not exists public.dle_schedule_backup (
  file text not null,
  game_id text not null references public.dle_games(id) on delete cascade,
  bank_day smallint not null check (bank_day between 1 and 365),
  entity_id text not null,
  pool_hash text,
  saved_at timestamptz not null default now(),
  primary key (file, game_id, bank_day)
);
alter table public.dle_schedule_backup enable row level security;
revoke all on table public.dle_schedule_backup from public, anon, authenticated;

create or replace function public.dle_reschedule(p_file text, p_game text, p_now timestamptz default now()) returns integer
language plpgsql set search_path = public
as $rs$
declare
  g public.dle_games;
  v_today date := public.dle_utc_date(p_now);
  v_tb integer;
  v_d date;
  v_b integer;
  v_cur text;
  v_pick text;
  v_n integer := 0;
begin
  select * into g from public.dle_games where id = p_game;
  if not found then
    raise exception 'dle_unknown_game';
  end if;
  -- A game that is not live yet has no calendar to protect: its activation will draw from the pool as it is.
  if g.epoch is null or not exists (select 1 from public.dle_schedule where game_id = p_game) then
    return 0;
  end if;
  insert into public.dle_schedule_backup (file, game_id, bank_day, entity_id, pool_hash)
  select p_file, s.game_id, s.bank_day, s.entity_id, g.pool_hash from public.dle_schedule s where s.game_id = p_game
  on conflict (file, game_id, bank_day) do nothing;
  v_tb := public.dle_bank_day(g.epoch, v_today);
  for k in 1..364 loop
    v_d := v_today + k;
    v_b := public.dle_bank_day(g.epoch, v_d);
    if v_b = v_tb or exists (select 1 from public.dle_daily_stats d where d.game_id = p_game and d.play_date = v_d) then
      continue;
    end if;
    select s.entity_id into v_cur from public.dle_schedule s where s.game_id = p_game and s.bank_day = v_b;
    if not found then
      continue;
    end if;
    if exists (select 1 from public.dle_entities e where e.game_id = p_game and e.entity_id = v_cur and e.can_be_target and e.in_pool
      and not exists (select 1 from public.dle_curation c where c.game_id = p_game and c.entity_id = e.entity_id and c.excluded)) then
      continue;
    end if;
    v_pick := null;
    for lvl in 1..3 loop
      select e.entity_id into v_pick from public.dle_entities e
      where e.game_id = p_game and e.can_be_target and e.in_pool
        and not exists (select 1 from public.dle_curation c where c.game_id = p_game and c.entity_id = e.entity_id and c.excluded)
        and (lvl = 3 or not exists (select 1 from public.dle_schedule s where s.game_id = p_game and s.entity_id = e.entity_id
          and s.bank_day in (select public.dle_bank_day(g.epoch, v_today + j) from generate_series(1, 30) as j)))
        and (lvl >= 2 or not exists (select 1 from public.dle_schedule s where s.game_id = p_game and s.entity_id = e.entity_id
          and s.bank_day in (select public.dle_bank_day(g.epoch, v_d + j) from generate_series(-30, 30) as j)))
      order by md5(p_game || ':' || v_b || ':' || e.entity_id), e.entity_id limit 1;
      exit when v_pick is not null;
    end loop;
    if v_pick is null then
      raise exception 'dle_reschedule: no valid target for %', p_game;
    end if;
    update public.dle_schedule set entity_id = v_pick, drawn_at = p_now where game_id = p_game and bank_day = v_b;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$rs$;

create or replace function public.dle_reschedule_undo(p_file text, p_game text, p_now timestamptz default now()) returns integer
language plpgsql set search_path = public
as $rs$
declare
  g public.dle_games;
  v_tb integer;
  v_hash text;
  v_n integer;
begin
  select * into g from public.dle_games where id = p_game;
  if not found then
    raise exception 'dle_unknown_game';
  end if;
  select b.pool_hash into v_hash from public.dle_schedule_backup b where b.file = p_file and b.game_id = p_game limit 1;
  if not found then
    return 0;
  end if;
  v_tb := public.dle_bank_day(g.epoch, public.dle_utc_date(p_now));
  update public.dle_schedule s set entity_id = b.entity_id, drawn_at = p_now
  from public.dle_schedule_backup b
  where b.file = p_file and b.game_id = p_game and s.game_id = p_game and s.bank_day = b.bank_day and s.entity_id <> b.entity_id
    and s.bank_day <> v_tb
    and not exists (select 1 from public.dle_daily_stats d where d.game_id = p_game and d.play_date >= public.dle_utc_date(p_now)
      and public.dle_bank_day(g.epoch, d.play_date) = s.bank_day);
  get diagnostics v_n = row_count;
  update public.dle_games set pool_hash = v_hash where id = p_game;
  delete from public.dle_schedule_backup where file = p_file and game_id = p_game;
  return v_n;
end;
$rs$;

revoke execute on function public.dle_reschedule(text, text, timestamptz), public.dle_reschedule_undo(text, text, timestamptz) from public, anon, authenticated;

declare
